insert into public.package_types (id, name, reference, markers) values
  ('retail', 'Retail package', 'Rule 2(k); Chapter II (Rules 3-18)', '{}'::text[]),
  ('wholesale', 'Wholesale package', 'Rule 2(r); Chapter III (Rule 24)', array['wholesale pack', 'wholesale package', 'for wholesale', 'not for retail sale individually', 'contains \d+ (retail )?(packs|packets|pouches|bottles)', '\d+\s*(retail )?(packs|packets|pouches|bottles) of \d+']::text[]),
  ('institutional', 'Institutional / industrial package', 'Rule 2(bc), Rule 3(c)', array['not for retail sale', 'for institutional use', 'for industrial use only', 'institutional pack', 'horeca', 'for catering']::text[]),
  ('export', 'Export package', 'Rule 25', array['for export only', 'export only', 'not for sale in india', 'not to be sold in india']::text[])
on conflict (id) do update set name = excluded.name, reference = excluded.reference, markers = excluded.markers;


